<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElButton, ElCheckbox, ElDialog, ElInput, ElMessage, ElSwitch, ElTable, ElTableColumn, vLoading } from 'element-plus'
import { httpClient } from '@/shared/http/client'
import type { ApiResponse, Page } from '@/shared/http/create-client'
import ShopMapSettings from '@/features/materials/ShopMapSettings.vue'
const mapShop=ref<number>()
interface Shop {id:number;name:string;code:string;enabled:boolean;contactName:string|null;contactPhone:string|null;address:string|null}
interface Region {id:number;name:string;code:string;level:number}
const rows=ref<Shop[]>([]),page=ref(1),total=ref(0),loading=ref(false),error=ref(''),dialog=ref(false),editing=ref<number|null>(null)
const form=reactive({name:'',code:'',enabled:true,contactName:'',contactPhone:'',address:''})
const serviceDialog=ref(false),serviceShop=ref<Shop>(),regionRows=ref<Region[]>([]),regionPage=ref(1),regionTotal=ref(0),selectedRegions=ref<number[]>([]),serviceBusy=ref(false)
async function load(){loading.value=true;error.value='';try{const response=await httpClient.get<ApiResponse<Page<Shop>>>('/admin/shops',{params:{page:page.value,size:20}});rows.value=response.data.data.records;total.value=response.data.data.total}catch(cause){error.value=cause instanceof Error?cause.message:'读取失败'}finally{loading.value=false}}
function open(value?:unknown){const row=value as Shop|undefined;editing.value=row?.id??null;Object.assign(form,{name:row?.name??'',code:row?.code??'',enabled:row?.enabled??true,contactName:row?.contactName??'',contactPhone:row?.contactPhone??'',address:row?.address??''});dialog.value=true}
async function save(){if(!form.name.trim()||!form.code.trim()){error.value='请填写网点名称与编码';return}loading.value=true;error.value='';try{const body={name:form.name.trim(),code:form.code.trim(),enabled:form.enabled,contactName:form.contactName.trim()||null,contactPhone:form.contactPhone.trim()||null,address:form.address.trim()||null};if(editing.value)await httpClient.put(`/admin/shops/${editing.value}`,body);else await httpClient.post('/admin/shops',body);dialog.value=false;ElMessage.success('网点已保存并审计');await load()}catch(cause){error.value=cause instanceof Error?cause.message:'保存失败'}finally{loading.value=false}}
async function loadRegions(){serviceBusy.value=true;error.value='';try{const response=await httpClient.get<ApiResponse<Page<Region>>>('/admin/regions',{params:{page:regionPage.value,size:20}});regionRows.value=response.data.data.records;regionTotal.value=response.data.data.total}catch(cause){error.value=cause instanceof Error?cause.message:'区域读取失败'}finally{serviceBusy.value=false}}
async function openServices(value:unknown){const shop=value as Shop;serviceShop.value=shop;serviceDialog.value=true;regionPage.value=1;selectedRegions.value=[];serviceBusy.value=true;error.value='';try{const response=await httpClient.get<ApiResponse<Page<number>>>(`/admin/shops/${shop.id}/service-regions`,{params:{page:1,size:100}});selectedRegions.value=response.data.data.records;await loadRegions()}catch(cause){error.value=cause instanceof Error?cause.message:'服务区域读取失败'}finally{serviceBusy.value=false}}
function toggleRegion(id:number,checked:boolean){selectedRegions.value=checked?[...selectedRegions.value,id]:selectedRegions.value.filter(value=>value!==id)}
async function saveServices(){if(!serviceShop.value)return;serviceBusy.value=true;error.value='';try{await httpClient.put(`/admin/shops/${serviceShop.value.id}/service-regions`,{regionIds:selectedRegions.value});serviceDialog.value=false;ElMessage.success('服务区域已保存并审计')}catch(cause){error.value=cause instanceof Error?cause.message:'保存失败'}finally{serviceBusy.value=false}}
onMounted(()=>{void load()})
</script>
<template><div class="work-page"><header class="module-page-head"><p>ADMIN / SHOPS</p><h1>维修网点</h1><span>网点资料与服务区域由管理员维护；按服务端分页查看。</span></header><section class="admin-surface"><div class="admin-toolbar"><ElButton type="primary" @click="open()">新增网点</ElButton><ElButton @click="load">刷新</ElButton></div><p v-if="error" role="alert" class="error-message">{{ error }}</p><ElTable v-loading="loading" :data="rows" empty-text="暂无网点"><ElTableColumn prop="name" label="网点名称" min-width="180"/><ElTableColumn prop="code" label="编码" min-width="120"/><ElTableColumn prop="contactName" label="联系人" min-width="100"/><ElTableColumn prop="contactPhone" label="联系电话" min-width="140"/><ElTableColumn prop="address" label="地址" min-width="220"/><ElTableColumn label="状态" width="80"><template #default="scope">{{ scope.row.enabled?'启用':'停用' }}</template></ElTableColumn><ElTableColumn label="操作" width="190"><template #default="scope"><ElButton text @click="open(scope.row)">编辑</ElButton><ElButton text @click="openServices(scope.row)">服务区域</ElButton><ElButton text @click="mapShop=scope.row.id">车型与位置</ElButton></template></ElTableColumn></ElTable><div class="admin-pager"><ElButton :disabled="loading||page<=1" @click="page--;load()">上一页</ElButton><span>第 {{ page }} 页 · 共 {{ total }} 条</span><ElButton :disabled="loading||page*20>=total" @click="page++;load()">下一页</ElButton></div></section><ElDialog v-model="dialog" :title="editing?'编辑网点':'新增网点'" width="min(560px,calc(100vw - 32px))"><div class="admin-form"><label>网点名称<ElInput v-model="form.name" maxlength="100"/></label><label>编码<ElInput v-model="form.code" maxlength="32"/></label><label>联系人<ElInput v-model="form.contactName" maxlength="100"/></label><label>联系电话<ElInput v-model="form.contactPhone" maxlength="32"/></label><label>地址<ElInput v-model="form.address" maxlength="255"/></label><label>启用<ElSwitch v-model="form.enabled"/></label></div><template #footer><ElButton @click="dialog=false">取消</ElButton><ElButton type="primary" :loading="loading" @click="save">保存</ElButton></template></ElDialog><ElDialog v-model="serviceDialog" :title="`${serviceShop?.name??''} · 服务区域`" width="min(580px,calc(100vw - 32px))"><p>已选择 {{ selectedRegions.length }} 个区域；跨页选择会保留。服务端最终校验区域层级与范围。</p><p v-if="error" role="alert" class="error-message">{{ error }}</p><div class="region-picks" :aria-busy="serviceBusy"><label v-for="region in regionRows" :key="region.id"><ElCheckbox :model-value="selectedRegions.includes(region.id)" @change="checked=>toggleRegion(region.id,Boolean(checked))">{{ region.name }}（{{ region.code }}）</ElCheckbox></label></div><div class="admin-pager"><ElButton :disabled="serviceBusy||regionPage<=1" @click="regionPage--;loadRegions()">上一页</ElButton><span>第 {{ regionPage }} 页 · 共 {{ regionTotal }} 个区域</span><ElButton :disabled="serviceBusy||regionPage*20>=regionTotal" @click="regionPage++;loadRegions()">下一页</ElButton></div><template #footer><ElButton @click="serviceDialog=false">取消</ElButton><ElButton type="primary" :loading="serviceBusy" @click="saveServices">保存服务区域</ElButton></template></ElDialog><ElDialog :model-value="mapShop!=null" title="网点车型与位置" width="min(900px,96vw)" @close="mapShop=undefined"><ShopMapSettings v-if="mapShop" :shop-id="mapShop" :address="rows.find(row=>row.id===mapShop)?.address??null"/></ElDialog></div></template>
<style scoped>.region-picks{display:grid;grid-template-columns:1fr 1fr;gap:6px;max-height:380px;overflow:auto;padding:12px;border:1px solid var(--color-border);border-radius:8px}@media(max-width:600px){.region-picks{grid-template-columns:1fr}}</style>
